        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    if cache.get(key(*args, **kwargs)):
                        return cache.get(key(*args, **kwargs))
                    else:
                        cache.set(key(*args, **kwargs), fn(*args, **kwargs))
