    Return a dictionary with options that deprecate other options.

    :returns: A dictionary with options that deprecate other options.
    :rtype: dict[str, dict[str, Union[str, Set[str]]]]
    """
    deprecated_args = {}
    for option in self.args:
        if 'deprecates' in option.metadata:
            for deprecated_option in option.metadata['deprecates']:
                deprecated_args[option.name] = {'deprecates': deprecated_option, 'warning': option.metadata['warning']}
    return deprecated_args

